    for k in range(3): c.drawPath(smooth([(470, 930 + k * 34), (540, 918 + k * 34), (610, 930 + k * 34)], False), line((214, 80, 30), 12))
    e = smooth([(540, 900), (556, 950), (540, 1000), (524, 950)]); c.drawPath(e, fill((190, 30, 20)))
