    c.save(); c.translate(250, 1420); c.rotate(24); sk = (92, 90, 140); G(smooth([(-240, -30), (-200, -120), (-40, -150), (120, -120), (180, -20), (140, 90), (-40, 120), (-200, 80)]), sk); G(smooth([(-200, -120), (-100, -200), (20, -190), (100, -130), (-20, -120)]), (50, 40, 80)); [G(smooth([(x, 60), (x - 14, 140), (x + 6, 210), (x + 50, 205), (x + 46, 120), (x + 60, 60)]), sk) for x in (-190, -70, 60)]; G(smooth([(100, -110), (200, -130), (280, -60), (380, 10), (380, 70), (310, 90), (180, 80), (110, 30)]), sk); G(smooth([(350, 0), (400, 10), (404, 70), (360, 80)]), (214, 150, 160)); [c.drawCircle(382, y, 8, fill(ink)) for y in (28, 54)]; G(smooth([(290, 70), (330, 60), (360, 0), (350, -60), (320, 10)]), (255, 250, 230)); G(smooth([(150, -110), (140, -190), (210, -130)]), sk); c.drawCircle(234, -40, 13, fill((255, 220, 120))); c.drawCircle(236, -40, 6, fill(ink)); c.drawPath(smooth([(-200, 10), (-40, 60), (140, 20)], False), line((250, 200, 70), 16)); G(poly([(120, -140), (112, -210), (150, -176), (176, -236), (200, -170), (240, -190), (226, -130)]), (250, 200, 70)); c.restore()
